const raw = $json.params?.id_activo;
const id = Number(raw);
const valido = raw !== undefined && raw !== null && String(raw).trim() !== '' && Number.isSafeInteger(id) && id > 0;
return [{ json: { valido, id_activo: valido ? id : null } }];

const raw = $json.query?.id_lote;
const value = typeof raw === 'string' ? raw.trim() : raw;
const valid = value !== undefined && value !== null && String(value).trim() !== '' && /^\d+$/.test(String(value).trim()) && Number.isSafeInteger(Number(value)) && Number(value) > 0;
return [{ json: valid
  ? { valid: true, id_lote: String(value).trim() }
  : { valid: false, statusCode: 400, error: 'id_lote es obligatorio y debe ser un entero positivo.' }
}];
